/// Image asset paths. Resolution variants live in the `2.0x/` and `3.0x/`
/// folders next to each file; they are generated by
/// `tool/figma/build_assets.py` from the Figma renders and image fills.
abstract final class AppImages {
  static const splashBackground = 'assets/img/splash/splash_background.webp';

  static const onboardingIntro1 = 'assets/img/onboarding/intro_1.webp';
  static const onboardingIntro2 = 'assets/img/onboarding/intro_2.webp';
  static const onboardingIntro3 = 'assets/img/onboarding/intro_3.webp';
  static const onboardingIntro4 = 'assets/img/onboarding/intro_4.webp';

  /// Dunes and clouds behind Home, New Habit and Courses (555 × 543 pt).
  static const dunes = 'assets/img/home/background.webp';

  /// The sample user's avatar illustration (60 pt).
  static const avatar = 'assets/img/profile/avatar.webp';
}

/// Auth screen artwork.
abstract final class AuthImages {
  /// 414×692 pt; fades into the background color at the bottom.
  static const loginBackground = 'assets/img/auth/login_background.webp';
  static const signUp = 'assets/img/auth/sign_up.webp';
  static const resetPassword = 'assets/img/auth/reset_password.webp';
}

/// Brand logos with their Figma drop shadows, on a 55×55 pt canvas with the
/// 23×23 pt logo at (16, 8). Generated by `tool/figma/build_icons.py`.
abstract final class BrandImages {
  static const google = 'assets/img/brand/google.webp';

  /// Not in the design (Apple replaced Facebook): drawn by
  /// `build_icons.py` with the same shadow.
  static const apple = 'assets/img/brand/apple.webp';
}

/// Bottom navigation tab illustrations, in color. Inactive tabs are drawn
/// in grayscale.
abstract final class NavImages {
  static const home = 'assets/img/nav/home.webp';
  static const courses = 'assets/img/nav/courses.webp';
  static const community = 'assets/img/nav/community.webp';
  static const settings = 'assets/img/nav/settings.webp';
}

/// Habit screens artwork.
abstract final class HabitImages {
  /// The hiker on the Home quote card (204 × 146 pt, right-aligned).
  static const quoteArt = 'assets/img/home/quote_art.webp';

  /// Round avatar above the New Habit tip card (70 pt).
  static const startAvatar = 'assets/img/habits/start_avatar.webp';

  /// Teepee illustration (congratulation popup, habit thumbnail).
  static const teepee = 'assets/img/habits/teepee.webp';
}

/// Courses artwork and sample course photos.
abstract final class CourseImages {
  static const banner = 'assets/img/courses/banner.webp';
  static const journalChallenge = 'assets/img/courses/journal_challenge.webp';
  static const selfHelpSeries = 'assets/img/courses/self_help_series.webp';
}

/// Sample community member photos (40 pt).
abstract final class CommunityImages {
  static const members = [
    'assets/img/community/member_1.webp',
    'assets/img/community/member_2.webp',
    'assets/img/community/member_3.webp',
    'assets/img/community/member_4.webp',
  ];
}

/// Settings and premium artwork.
abstract final class SettingsImages {
  /// "Check Your Profile" card illustration (222 × 146 pt).
  static const profileArt = 'assets/img/settings/profile_art.webp';

  /// Premium offer card teepee (181 × 146 pt).
  static const offerArt = 'assets/img/premium/offer_art.webp';
}
